package com.anderson.onedrivesync.sync

import java.io.File
import org.junit.Assert.assertEquals
import org.junit.Test
import org.junit.runner.RunWith
import org.junit.runners.Parameterized

/**
 * Known-answer vectors from docs/quickxor-vectors.txt (generated by tools/quickxor_ref.py and
 * cross-checked against Microsoft's reference implementation).
 */
@RunWith(Parameterized::class)
class QuickXorHashTest(
    private val vectorName: String,
    private val input: ByteArray,
    private val expected: String,
) {
    @Test
    fun `matches microsoft vector`() {
        assertEquals("vector $vectorName", expected, hashBytes(input))
    }

    @Test
    fun `streamed in irregular chunks matches one shot`() {
        assertEquals("vector $vectorName", expected, hashInIrregularChunks(input))
    }

    private fun hashInIrregularChunks(data: ByteArray): String {
        val hash = QuickXorHash()
        val chunkSizes = intArrayOf(1, 7, 63, 1000)
        var offset = 0
        var chunk = 0
        while (offset < data.size) {
            val length = minOf(chunkSizes[chunk % chunkSizes.size], data.size - offset)
            hash.update(data, offset, length)
            offset += length
            chunk++
        }
        return hash.digest().toHexString()
    }

    companion object {
        @JvmStatic
        @Parameterized.Parameters(name = "{0}")
        fun vectors(): List<Array<Any>> = listOf(
            arrayOf("empty", ByteArray(0), "0000000000000000000000000000000000000000"),
            arrayOf("one_byte_00", byteArrayOf(0x00), "0000000000000000000000000100000000000000"),
            arrayOf("one_byte_61", byteArrayOf(0x61), "6100000000000000000000000100000000000000"),
            arrayOf(
                "hello_world",
                "hello world".toByteArray(),
                "6828031bd8f00610dce10d726b03190000000000",
            ),
            arrayOf(
                "pangram",
                "The quick brown fox jumps over the lazy dog".toByteArray(),
                "6cc4a56f2b26c492fa4bbe57c1f31c4193a972be",
            ),
            arrayOf("160_bytes", ByteArray(160) { it.toByte() }, "ffe1062e59d08b4755b39384ad75a1127cf9c20e"),
            arrayOf(
                "161_bytes",
                ByteArray(162) { if (it < 161) it.toByte() else 'x'.code.toByte() },
                "5f21052e59d08b4755b39384af75a1127cf9c20e",
            ),
            arrayOf("random_4k", random4k(), "a2eeadb0c21177081f7dc1b71a834f35e52533ae"),
            arrayOf("zeros_10k", ByteArray(10_000), "0000000000000000000000001027000000000000"),
            arrayOf("seven_bytes", "abcdefg".toByteArray(), "6110c318c85006339c0100000700000000000000"),
        )

        /** The exact bytes generated by `random.Random(1234).randrange(256)` x4096 in the Python reference. */
        private fun random4k(): ByteArray {
            val stream = QuickXorHashTest::class.java.getResourceAsStream("/quickxor_random_4k.bin")
            checkNotNull(stream) { "missing test resource quickxor_random_4k.bin" }
            return stream.use { it.readBytes() }
        }
    }
}

class QuickXorHashFileTest {
    @Test
    fun `hashFile streams file larger than one mebibyte`() {
        val content = ByteArray(1_200_000) { ((it * 31 + 7) and 0xFF).toByte() }
        val file = File.createTempFile("quickxor", ".bin")
        try {
            file.writeBytes(content)
            assertEquals("fc1c18bf07c2ef01f07f007c9f4bcd87c1f36170", hashFile(file))
            assertEquals(hashBytes(content), hashFile(file))
        } finally {
            file.delete()
        }
    }

    @Test
    fun `reset clears the accumulated state`() {
        val hash = QuickXorHash()
        hash.update("hello world".toByteArray())
        hash.reset()
        assertEquals(hashBytes(ByteArray(0)), hash.digest().toHexString())
        assertEquals(20, hash.digest().size)
    }
}

private fun ByteArray.toHexString(): String = joinToString("") { "%02x".format(it) }
